head.b:skin:
/* ============================================================
   AMS Editorial - tokens. The only place colours / radii / widths are set.
   Contrast-checked pairs (audit): --ink, --ink-2, --accent on --surface /
   --surface-2 / --bg, and --on-navy(-2) on --navy(-2). Never lighten.
   ============================================================ */
:root{
  color-scheme:light;
  --bg:#F4F7FC; --surface:#FFFFFF; --surface-2:#EDF2FA; --tint:#E8F1FF;
  --ink:#0B1220; --ink-2:#3D4757; --ink-3:#5A6577;
  --line:#E2E8F2; --line-2:#CFDAEA;
  --navy:#0B1220; --navy-2:#111E36; --on-navy:#DCE6F5; --on-navy-2:#9ECBFF;
  --brand-1:#409CFF; --brand-2:#005CD6; --accent:#0050BC; --accent-2:#003E99;
  --grad:linear-gradient(90deg,#0B63D6,#0047B3);
  --grad-red:linear-gradient(90deg,#C42B25,#8E1414);
  --mark:linear-gradient(90deg,var(--brand-1),var(--brand-2));
  --r:14px; --r-s:9px; --r-l:20px;
  --sh:0 1px 2px rgba(11,18,32,.05),0 18px 44px -26px rgba(11,18,32,.30);
  --sh-s:0 1px 2px rgba(11,18,32,.06);
  --wrap:1240px; --read:700px; --rail:318px; --gut:clamp(18px,4.4vw,44px); --bar:62px;
  --font:'Inter',-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,'Helvetica Neue',Arial,'Noto Sans',sans-serif;
  --mono:ui-monospace,SFMono-Regular,'SF Mono',Menlo,Consolas,'Liberation Mono',monospace;
}

/* ---------------- base ---------------- */
*,*::before,*::after{box-sizing:border-box}
html{-webkit-text-size-adjust:100%;scroll-behavior:smooth;scroll-padding-top:calc(var(--bar) + 22px)}
body{
  margin:0;background:var(--bg);color:var(--ink);
  font-family:var(--font);font-size:16.5px;line-height:1.68;
  -webkit-font-smoothing:antialiased;
}
/* Blogger's widget/section wrappers must not interfere with our grid */
.section,.sec,.widget,.widget-content{display:contents}
img,svg{max-width:100%;height:auto}
img{border-style:none}
h1,h2,h3,h4{margin:0;line-height:1.14;letter-spacing:-.024em;text-wrap:balance}
p{margin:0 0 1.05em}
a{color:var(--accent);text-decoration:none;-webkit-tap-highlight-color:transparent}
a:hover{color:var(--accent-2);text-decoration:underline;text-underline-offset:2px}
:focus-visible{outline:2px solid var(--brand-1);outline-offset:2px;border-radius:5px}
::selection{background:var(--tint);color:var(--ink)}
.wrap{width:100%;max-width:var(--wrap);margin:0 auto;padding:0 var(--gut)}
.vh{position:absolute!important;width:1px;height:1px;overflow:hidden;clip-path:inset(50%);white-space:nowrap}
.skip{
  position:absolute;left:12px;top:-72px;z-index:40;padding:12px 18px;border-radius:var(--r-s);
  background:var(--surface);box-shadow:var(--sh);color:var(--ink);font-weight:700;font-size:14px;
}
.skip:focus{top:12px;color:var(--accent)}
.kicker{
  display:inline-flex;align-items:center;gap:10px;margin:0 0 16px;padding:6px 15px 6px 8px;
  border:1px solid var(--line-2);border-radius:999px;background:rgba(255,255,255,.86);
  font-size:12.5px;font-weight:800;letter-spacing:.11em;text-transform:uppercase;color:var(--ink-2);
}
.kicker i{display:inline-block;width:22px;height:22px;flex:0 0 auto;border-radius:7px;background:var(--grad)}

/* ---------------- masthead (navy, sticky from tablet up) ---------------- */
.hdr{position:relative;z-index:30;color:#fff;background:linear-gradient(180deg,var(--navy-2),var(--navy))}
.hdr::after{content:'';display:block;height:2px;background:var(--mark)}
.hdr-in{display:flex;flex-direction:column;align-items:stretch;gap:2px;padding-top:12px}
.brand{display:inline-flex;align-items:center;gap:12px;color:#fff;text-decoration:none;padding:0 0 10px}
.brand:hover{color:#fff;text-decoration:none}
.mark{display:block;flex:0 0 auto;border-radius:10px}
.brand-tx{display:flex;flex-direction:column;min-width:0;line-height:1.14}
.brand-name{margin:0;font-size:19px;font-weight:800;letter-spacing:.2em;color:#fff}
.brand-tag{font-size:12.5px;font-weight:600;letter-spacing:.02em;color:var(--on-navy-2)}
.brand:hover .brand-name{color:var(--on-navy-2)}
.nav{
  position:relative;margin:0 calc(var(--gut) * -1);padding:0 var(--gut);
  border-top:1px solid rgba(255,255,255,.13);
  overflow-x:auto;scrollbar-width:none;-webkit-overflow-scrolling:touch;
}
.nav::-webkit-scrollbar{display:none}
.tablist{display:flex;align-items:stretch;gap:2px;list-style:none;margin:0;padding:0}
.tablist li{display:flex}
.tab{
  display:inline-flex;align-items:center;gap:8px;min-height:44px;padding:0 14px;
  border-bottom:2px solid transparent;color:var(--on-navy);
  font-size:14px;font-weight:600;letter-spacing:.02em;white-space:nowrap;
  transition:color .16s,background-color .16s,border-color .16s;
}
.tab:hover{color:#fff;background:rgba(255,255,255,.07);border-bottom-color:rgba(255,255,255,.42);text-decoration:none}
.tab.on{color:#fff;border-bottom-color:var(--brand-1);background:linear-gradient(180deg,rgba(64,156,255,0),rgba(64,156,255,.16))}
.tab.yt{
  align-self:center;min-height:38px;margin:0 0 2px 8px;padding:0 16px;border-bottom:0;border-radius:999px;
  background:var(--grad-red);color:#fff;font-weight:700;
}
.tab.yt:hover{background:var(--grad-red);color:#fff;filter:brightness(1.12)}

/* ---------------- hero band ---------------- */
.band{
  background:var(--bg);
  background-image:radial-gradient(920px 420px at 8% -30%,rgba(64,156,255,.20),transparent 70%),linear-gradient(180deg,var(--tint),rgba(244,247,252,0) 78%);
  border-bottom:1px solid var(--line);padding:clamp(28px,5.4vw,60px) 0 clamp(24px,4.2vw,46px);
}
.band.is-slim{padding:clamp(22px,3.4vw,36px) 0;background-image:linear-gradient(180deg,var(--tint),rgba(244,247,252,0) 82%)}
.band-in{display:grid;gap:clamp(20px,3.2vw,34px)}
.band-a{min-width:0}
.band-t{font-size:clamp(31px,6.1vw,56px);font-weight:800;letter-spacing:-.036em;line-height:1.03}
.band.is-slim .band-t{font-size:clamp(26px,3.8vw,38px)}
.band-s{margin:16px 0 0;max-width:56ch;font-size:clamp(16.5px,1.95vw,19.5px);line-height:1.6;color:var(--ink-2);text-wrap:pretty}
.band.is-slim .band-s{margin-top:10px;font-size:16.5px}
.band-cta{display:flex;flex-wrap:wrap;gap:10px;margin:26px 0 0}
.band-cta a{flex:1 1 auto}
.band-x{display:grid;grid-template-columns:repeat(auto-fit,minmax(132px,1fr));gap:16px 22px;margin:0;padding:20px 0 0;border-top:1px solid var(--line-2);list-style:none}
.band-x li{min-width:0}
.band-x b{display:block;font-size:21px;font-weight:800;letter-spacing:-.02em;line-height:1.2;color:var(--ink)}
.band-x span{display:block;margin-top:3px;font-size:12px;font-weight:700;letter-spacing:.1em;text-transform:uppercase;color:var(--ink-2);text-wrap:pretty}

/* ---------------- buttons ---------------- */
.btn{
  display:inline-flex;align-items:center;justify-content:center;gap:9px;
  min-height:46px;padding:11px 22px;border:1px solid transparent;border-radius:999px;
  background:var(--surface);color:var(--ink);font-size:15px;font-weight:700;line-height:1;white-space:nowrap;
  transition:transform .14s,box-shadow .16s,filter .16s,background-color .16s,border-color .16s;
}
.btn:hover{text-decoration:none;transform:translateY(-1px)}
.btn:active{transform:translateY(0)}
.btn-primary{background:var(--grad);color:#fff;box-shadow:inset 0 1px 0 rgba(255,255,255,.26),var(--sh-s)}
.btn-primary:hover{color:#fff}
.btn-red{background:var(--grad-red);color:#fff}
.btn-red:hover{color:#fff;filter:brightness(1.08)}
.btn-ghost{border-color:var(--line-2);color:var(--accent);background:rgba(255,255,255,.72)}
.btn-ghost:hover{border-color:var(--brand-2);background:var(--surface);color:var(--accent-2)}
.btn .ar::after{content:'\2192';margin-left:9px;font-weight:600}
.post-body .btn{color:#fff;text-decoration:none}

/* ---------------- page grid ---------------- */
.cols{display:grid;gap:clamp(26px,3.4vw,46px);padding:clamp(22px,3.4vw,40px) 0 8px}
.main{min-width:0}
.rail{display:grid;gap:14px;align-content:start;min-width:0}
.back{display:inline-flex;align-items:center;gap:8px;min-height:40px;margin:0 0 14px;font-size:14px;font-weight:700;color:var(--ink-2)}
.back::before{content:'\2190';transition:transform .16s ease-out}
.back:hover{color:var(--accent);text-decoration:none}
.back:hover::before{transform:translateX(-3px)}

/* ---------------- feed: featured lead + index rows ---------------- */
.feed{display:grid}
.card{position:relative;padding:clamp(20px,2.6vw,26px) 0;border-top:1px solid var(--line)}
.card::before{content:'';position:absolute;left:0;top:-1px;width:0;height:2px;background:var(--mark);transition:width .2s ease-out}
.card:hover::before{width:64px}
.card:hover>.card-t a{color:var(--accent)}
.card-t{font-size:clamp(20px,2.4vw,25px);font-weight:700;letter-spacing:-.022em;line-height:1.22}
.card-t a{color:var(--ink)}
.card-t a:hover{color:var(--accent);text-decoration:none}
.meta{display:flex;flex-wrap:wrap;align-items:center;gap:10px;margin:11px 0 0;font-size:12.5px;font-weight:700;letter-spacing:.1em;text-transform:uppercase;color:var(--ink-2)}
.meta .who{color:var(--accent)}
.meta .dot{width:4px;height:4px;border-radius:50%;background:var(--line-2)}
.excerpt{margin:12px 0 0;max-width:68ch;color:var(--ink-2);font-size:16px;text-wrap:pretty}
.more{display:inline-flex;align-items:center;gap:7px;margin-top:15px;font-size:15px;font-weight:700;min-height:34px}
.more::after{content:'\2192';transition:transform .16s ease-out}
.more:hover::after{transform:translateX(3px)}
/* on the homepage the newest post is the lead story, not just another row */
.feed .chips{margin-top:16px;padding-top:0;border-top:0}
.is-lead>:first-child{
  padding:clamp(18px,2.4vw,28px);margin:0 0 clamp(8px,1.4vw,16px);
  border:1px solid var(--line);border-radius:var(--r-l);background:var(--surface);box-shadow:var(--sh);
}
.is-lead>:first-child::before{display:none}
.is-lead>:first-child::after{content:'Latest';display:block;margin:0 0 13px;font-size:12px;font-weight:800;letter-spacing:.14em;text-transform:uppercase;color:var(--accent-2)}
.is-lead>:first-child .card-t{font-size:clamp(24px,3.1vw,34px);letter-spacing:-.03em}
.is-lead>:first-child .excerpt{font-size:17px;margin-top:14px}
.is-lead>:first-child:hover{border-color:var(--line-2)}

/* ---------------- article ---------------- */
.post{background:var(--surface);border:1px solid var(--line);border-radius:var(--r-l);box-shadow:var(--sh);padding:clamp(22px,4vw,46px);margin:0 0 22px}
.post-t{font-size:clamp(29px,4.7vw,46px);font-weight:800;letter-spacing:-.034em;line-height:1.07}
.post-body{margin-top:24px;font-size:17.5px;line-height:1.75;color:var(--ink)}
.post-body>*:last-child{margin-bottom:0}
.post-body>p:first-of-type{font-size:clamp(18px,2vw,20.5px);line-height:1.6;color:var(--ink-2);max-width:62ch}
.post-body h2{margin:1.9em 0 .55em;font-size:clamp(22px,2.9vw,29px);font-weight:700;letter-spacing:-.026em}
.post-body h3{margin:1.55em 0 .45em;font-size:clamp(18px,2.2vw,21px);font-weight:700}
.post-body h4{margin:1.4em 0 .4em;font-size:17px;font-weight:700;letter-spacing:.01em}
.post-body h2,.post-body h3,.post-body h4{scroll-margin-top:calc(var(--bar) + 24px)}
.post-body a{font-weight:600;text-decoration:underline;text-decoration-thickness:1px;text-underline-offset:2px}
.post-body ul,.post-body ol{margin:0 0 1.15em;padding-left:22px}
.post-body li{margin:7px 0}
.post-body li::marker{color:var(--brand-2)}
.post-body strong{font-weight:700}
.post-body img{display:block;margin:22px 0;border:1px solid var(--line);border-radius:var(--r);box-shadow:var(--sh-s)}
.post-body hr{margin:32px 0;border:0;border-top:1px solid var(--line)}
.post-body blockquote{
  margin:28px 0;padding:18px 24px;border-left:3px solid var(--brand-2);
  background:var(--surface-2);border-radius:0 var(--r) var(--r) 0;color:var(--ink);font-size:18px;line-height:1.6;
}
.post-body blockquote p:last-child{margin-bottom:0}
.post-body code,.post-body pre{font-family:var(--mono);font-size:.9em;overflow-wrap:break-word}
.post-body code{padding:.14em .42em;background:var(--surface-2);border:1px solid var(--line);border-radius:6px}
.post-body pre{margin:24px 0;padding:18px 20px;border-radius:var(--r);background:var(--navy);color:#EEF3FA;overflow:auto;line-height:1.62}
.post-body pre code{padding:0;background:none;border:0;color:inherit}
.post-body table{width:100%;margin:24px 0;border-collapse:collapse;font-size:16px}
.post-body th,.post-body td{padding:10px 13px;border:1px solid var(--line);text-align:left}
.post-body th{background:var(--surface-2);font-size:13px;letter-spacing:.07em;text-transform:uppercase;color:var(--ink-2)}
.post-body tbody tr:nth-child(even) td{background:rgba(237,242,250,.5)}
.post-body figure{margin:22px 0}
.post-body figcaption{margin-top:9px;font-size:14px;color:var(--ink-2);text-align:center}
.chips{display:flex;flex-wrap:wrap;gap:8px;margin-top:26px;padding-top:22px;border-top:1px solid var(--line)}
.chip{
  display:inline-flex;align-items:center;min-height:34px;padding:6px 14px;border-radius:999px;
  background:var(--surface-2);border:1px solid var(--line);color:var(--accent);
  font-size:13.5px;font-weight:700;letter-spacing:.02em;
}
.chip:hover{background:var(--tint);border-color:var(--brand-1);color:var(--accent-2);text-decoration:none}

/* ---------------- rail widgets ---------------- */
.wg{background:var(--surface);border:1px solid var(--line);border-radius:var(--r);box-shadow:var(--sh-s);padding:clamp(16px,2.2vw,22px)}
.wg-t{display:flex;align-items:center;gap:12px;margin:0 0 13px;font-size:12px;font-weight:800;letter-spacing:.15em;text-transform:uppercase;color:var(--ink-2)}
.wg-t::after{content:'';flex:1 1 auto;height:1px;background:var(--line)}
.wg ul{list-style:none;margin:0;padding:0}
.wg li+li{border-top:1px solid var(--line)}
.wg li a{display:flex;align-items:center;justify-content:space-between;gap:10px;min-height:40px;font-size:15px;color:var(--ink)}
.wg li a:hover{color:var(--accent);text-decoration:none}
.wg .n{padding:2px 9px;border-radius:999px;background:var(--surface-2);font-size:12.5px;font-weight:700;color:var(--ink-2)}
.wg-about{
  border-color:var(--navy);color:var(--on-navy);
  background:var(--navy);
  background-image:radial-gradient(240px 150px at 106% -14%,rgba(64,156,255,.42),transparent 72%);
}
.wg-about .wg-t{color:var(--on-navy-2)}
.wg-about .wg-t::after{background:rgba(255,255,255,.18)}
.wg-about p{margin-bottom:16px;font-size:15px;line-height:1.6;color:var(--on-navy)}
.wg-about .btn{width:100%}
.search{display:flex;gap:8px}
.search input{
  flex:1 1 auto;min-width:0;min-height:44px;padding:10px 14px;
  font:inherit;font-size:15px;color:var(--ink);
  background:var(--surface-2);border:1px solid var(--line-2);border-radius:var(--r-s);
}
.search input::placeholder{color:var(--ink-3)}
.search input:focus{background:var(--surface);border-color:var(--brand-2);outline:none;box-shadow:0 0 0 3px rgba(0,92,214,.16)}
.search button{
  flex:0 0 auto;display:inline-flex;align-items:center;justify-content:center;width:48px;min-height:44px;
  border:0;border-radius:var(--r-s);background:var(--grad);color:#fff;cursor:pointer;box-shadow:var(--sh-s);
}
.search button:hover{filter:brightness(1.08)}

/* ---------------- pager ---------------- */
.pager{display:flex;flex-wrap:wrap;gap:10px;align-items:center;justify-content:space-between;margin:26px 0 6px;padding-top:22px;border-top:1px solid var(--line)}
.pager a{
  display:inline-flex;align-items:center;gap:8px;min-height:44px;padding:10px 18px;
  border:1px solid var(--line-2);border-radius:999px;background:var(--surface);
  color:var(--ink);font-size:14.5px;font-weight:700;
}
.pager a:hover{border-color:var(--brand-2);color:var(--accent);text-decoration:none}

/* ---------------- footer (navy) ---------------- */
.ftr{margin-top:clamp(30px,5vw,62px);color:var(--on-navy);background:linear-gradient(180deg,var(--navy-2),var(--navy))}
.ftr-in{display:grid;gap:26px;padding:clamp(28px,4vw,48px) 0}
.ftr-b{display:inline-flex;align-items:center;gap:11px;font-size:17px;font-weight:800;letter-spacing:.2em;color:#fff}
.ftr-p{margin:14px 0 0;max-width:38ch;font-size:15px;line-height:1.6;color:var(--on-navy)}
.ftr-h{margin:0 0 12px;font-size:12px;font-weight:800;letter-spacing:.15em;text-transform:uppercase;color:var(--on-navy-2)}
.ftr-l{display:grid;gap:2px;list-style:none;margin:0;padding:0}
.ftr-l a{display:inline-flex;align-items:center;min-height:36px;font-size:14.5px;font-weight:600;color:var(--on-navy)}
.ftr-l a:hover{color:#fff;text-decoration:none}
.ftr-bar{display:flex;flex-wrap:wrap;gap:8px 22px;align-items:center;justify-content:space-between;padding:16px 0;border-top:1px solid rgba(255,255,255,.15);font-size:13.5px;color:var(--on-navy)}
.ftr-bar a{color:var(--on-navy-2);font-weight:700}
.ftr-bar a:hover{color:#fff}
.ftr-top{display:inline-flex;align-items:center;gap:8px;min-height:36px}

/* ---------------- 560px: phablet ---------------- */
@media (min-width:560px){
  body{font-size:17px}
  .band-cta a{flex:0 0 auto}
  .band-x{grid-template-columns:repeat(3,minmax(0,1fr))}
  .ftr-in{grid-template-columns:repeat(2,minmax(0,1fr))}
}
/* ---------------- 900px: tablet landscape ----------------
   masthead becomes one sticky row; the rail drops under the feed in 2 columns */
@media (min-width:900px){
  .hdr{position:sticky;top:0}
  .hdr-in{flex-direction:row;align-items:stretch;gap:var(--gut);min-height:var(--bar);padding-top:0;padding-bottom:0}
  .brand{align-self:center;padding:0}
  .brand-tag{display:block}
  .nav{display:flex;justify-content:flex-end;flex:1 1 auto;min-width:0;margin:0;padding:0;border-top:0}
  .tablist{flex:0 0 auto}
  .tab{padding:0 15px}
  .tab.yt{margin:0 0 0 8px;min-height:38px}
  .cols{padding-top:clamp(28px,3vw,42px)}
  .feed{grid-template-columns:repeat(2,minmax(0,1fr));column-gap:clamp(22px,2.6vw,34px)}
  .is-lead>:first-child,.pager{grid-column:1/-1}
  .card{padding-left:20px;padding-right:20px}
  .cols.is-post{grid-template-columns:minmax(0,780px);justify-content:center}
  .ftr-in{grid-template-columns:1.5fr 1fr 1fr;gap:40px}
  .rail{grid-template-columns:repeat(2,minmax(0,1fr))}
}
/* ---------------- 1080px: laptop / desktop - sidebar comes back ---------------- */
@media (min-width:1080px){
  .cols{grid-template-columns:minmax(0,1fr) var(--rail);align-items:start}
  .cols.is-post{grid-template-columns:minmax(0,var(--read)) var(--rail);justify-content:center}
  .rail{display:block;position:sticky;top:calc(var(--bar) + 22px)}
  .rail>.wg{margin:0 0 14px}
  .feed{grid-template-columns:minmax(0,1fr)}
  .band-in{grid-template-columns:minmax(0,1fr) 320px;align-items:end;gap:44px}
  .band-x{grid-template-columns:minmax(0,1fr);gap:14px;padding:0 0 0 24px;border-top:0;border-left:1px solid var(--line-2)}
  .band-x b{font-size:23px}
}
/* ---------------- 1440px+: large PC / ultrawide ---------------- */
@media (min-width:1440px){
  :root{--wrap:1360px;--gut:48px;--read:740px;--bar:68px}
  body{font-size:17.5px}
  .band{padding-top:74px;padding-bottom:58px}
  .band-t{font-size:64px}
  .band-s{font-size:20px;max-width:60ch}
  .cols{padding-top:46px;gap:56px}
  .is-lead>:first-child .card-t{font-size:38px}
  .card-t{font-size:26px}
  .post{padding:56px 60px}
  .post-t{font-size:50px}
}

/* ---------------- reduced motion / print ---------------- */
@media (prefers-reduced-motion:reduce){
  html{scroll-behavior:auto}
  *,*::before,*::after{animation-duration:.001ms!important;transition-duration:.001ms!important}
}
@media print{
  .hdr,.rail,.ftr,.band-cta,.band-x,.pager,.skip,.chips,.back{display:none}
  body{background:#fff;color:#000;font-size:12pt}
  .post{padding:0;border:0;box-shadow:none}
  .post-body a{color:#000}
}
